/**
 * Erwarteter Input (von LLM-Node):
 *   { text: "{ ...JSON... }" }
 *   oder { response: "{ ...JSON... }" }
 *
 * Output:
 *  - Wenn Name extrahierbar → { firstName, lastName, hint, keywords, raw, parsedRaw }
 *  - Wenn NICHT extrahierbar → { status: "not_found", data: null, message: "..." }
 */

const out = [];

for (const item of $items()) {
  const src = item.json || {};

  // ✅ Fix: nimm "text" (dein Input) oder fallback "response"
  const raw = String(src.text ?? src.response ?? "").trim();

  let parsed = null;
  let parseError = null;

  // -----------------------------
  // JSON aus raw extrahieren
  // -----------------------------
  try {
    // Versuch 1: raw ist reines JSON
    parsed = JSON.parse(raw);
  } catch (e1) {
    try {
      // Versuch 2: JSON ist eingebettet (z.B. Text davor/danach)
      const match = raw.match(/\{[\s\S]*\}/);
      if (!match) throw e1;
      parsed = JSON.parse(match[0]);
    } catch (e2) {
      parseError = e2;
      parsed = {
        firstName: null,
        lastName: null,
        hint: "Fehler beim Parsen",
        keywords: [],
        _parseError: String(parseError),
      };
    }
  }

  const firstName = parsed?.firstName ?? null;
  const lastName = parsed?.lastName ?? null;
  const hint = parsed?.hint ?? null;
  const keywords = Array.isArray(parsed?.keywords) ? parsed.keywords : [];

  // ---------------------------------------------------
  // NOT-FOUND-CHECK:
  // Wenn KEIN Name extrahiert wurde → not_found
  // ---------------------------------------------------
  if (!firstName && !lastName) {
    out.push({
      json: {
        status: "not_found",
        data: null,
        message: hint || "Es konnte keine Person aus dem Prompt extrahiert werden.",
        raw,
        parsedRaw: parsed,
      },
    });
    continue;
  }

  // ✅ Erfolgsfall
  out.push({
    json: {
      firstName,
      lastName,
      hint,
      keywords
    },
  });
}

return out;

// Input kommt vom PDF-Webhook so rein:
// {
//   headers: {...},
//   params: {...},
//   query: {...},
//   body: {
//     status: "ok",
//     data: { canonicalName, shortBio, facts, confidence },
//     message: "..."
//
//   },
//   ...
// }
//
// -> Wir müssen also aus item.json.body.data lesen, nicht aus item.json.data

const items = $items();
const out = [];

for (const item of items) {
  const root = item.json || {};
  const body = root.body || {};          // <--- WICHTIG
  const data = body.data || {};          // <--- HIER liegen canonicalName, shortBio etc.

  const name = data.canonicalName || '–';
  const shortBio = data.shortBio || '';
  const facts = Array.isArray(data.facts) ? data.facts : [];
  const confidence = typeof data.confidence === 'number'
    ? Math.round(data.confidence * 100)
    : null;

  // shortBio-Zeilenumbrüche in <p> + <br> umwandeln
  const bioHtml = shortBio
    ? shortBio
        .split(/\n{2,}/)
        .map(block => `<p>${block.replace(/\n/g, '<br>')}</p>`)
        .join('\n')
    : '<p>Keine Kurzbiografie vorhanden.</p>';

  const factsHtml = facts.length
    ? facts.map(f => {
        const key = f.key || '';
        const value = f.value || '';
        return `
          <div class="fact">
            <b>${key}</b>
            <div>${value}</div>
          </div>
        `;
      }).join('\n')
    : '<p>Keine zusätzlichen Fakten vorhanden.</p>';

  const confHtml = confidence !== null
    ? `<div class="confidence">Confidence: ${confidence}%</div>`
    : '';

  const html = `
<!doctype html>
<html>
<head>
  <meta charset="utf-8" />
  <title>Steckbrief – ${name}</title>
  <style>
    body { font-family: Arial, sans-serif; padding: 24px; color: #111; }
    h1 { font-size: 24px; margin-bottom: 4px; }
    h2 { margin-top: 24px; margin-bottom: 8px; font-size: 18px; }
    .subtitle { color: #555; margin-bottom: 12px; }
    .confidence { margin-top: 4px; color: #555; font-size: 12px; }
    .fact { margin-bottom: 10px; }
    .fact b { display: block; margin-bottom: 2px; }
    hr { margin: 20px 0; border: none; border-top: 1px solid #ddd; }
  </style>
</head>
<body>
  <h1>${name}</h1>
  <div class="subtitle">Automatisch generierter Steckbrief</div>
  ${confHtml}
  <hr />
  <h2>Kurzprofil</h2>
  ${bioHtml}
  <h2>Fakten & Quellen</h2>
  ${factsHtml}
</body>
</html>
`;

  out.push({
    json: {
      html
    }
  });
}

return out;

/**
 * Erwartet:
 * - Aktueller Node: LLM-Ergebnis
 *   item.json.text = JSON-String mit { name, text, confidence? }
 *
 * - Node "ParseHints":
 *   Items mit { rows: [...] }
 *
 * Mode: Run once for all items
 */

function hostLabel(url) {
  try {
    const u = new URL(String(url));
    return u.hostname.replace(/^www\./i, '');
  } catch {
    return 'Web';
  }
}

const results = [];
const parseHintsItems = $("ParseHints").all();

for (let i = 0; i < $items().length; i++) {
  const item = $items()[i];
  const raw = item.json.text;

  let parsed;
  try {
    parsed = typeof raw === "string" ? JSON.parse(raw) : raw;
  } catch (e) {
    parsed = {};
  }

  const name = parsed.name ?? null;
  const bio = parsed.text ?? null;

  // 👉 CONFIDENCE: NICHT anfassen, nur übernehmen
  // item-synchron aus der Node "Confidence" holen
const confFromNode =
    $items("Confidence", 0, $itemIndex)?.[0]?.json?.confidence;

// exakt deine gewünschte Logik
const lal = { confidence: confFromNode };

const confidence =
  typeof lal.confidence === "number"
    ? lal.confidence
    : null;


  const parseHint = parseHintsItems[i]?.json ?? {};
  const links = Array.isArray(parseHint.rows) ? parseHint.rows : [];

  // Guard: Mindestqualität (optional, aber empfohlen)
  if (!name || !bio) {
    results.push({
      json: {
        status: "invalid",
        reason: "missing_name_or_text",
        name,
        text: bio,
        confidence,
        links
      }
    });
    continue;
  }

  // ✅ sources -> facts (altes Format)
  const sources = links
    .filter(r => r && r.link)
    .map((r) => ({
      key: `Quelle: ${hostLabel(r.link)}`,
      value: r.link,
      source: "Web"
    }));

  results.push({
    json: {
      status: "ok",
      name,
      text: bio,
      confidence,
      sources
    }
  });
}

return results;

const rows = $('Abschneiden').first().json.rows ?? [];

// 1) Nur valide Cluster mit >= 3 Positionen zulassen
const clusters = ($json.clusters ?? [])
  .filter(c => Array.isArray(c.positions) && c.positions.length >= 3);

// Falls kein Cluster die Mindestanforderung erfüllt → leer zurück
if (clusters.length === 0) {
  return [];
}

// 2) Nach Größe sortieren (absteigend)
clusters.sort((a, b) => b.positions.length - a.positions.length);

// 3) Maximal Top 2 Cluster verwenden
const top = clusters.slice(0, 2);

// 4) Rows je Cluster sammeln + sortieren
const out = top.map((c, idx) => {
  const posSet = new Set(c.positions.map(Number));

  const filtered = rows
    .filter(r => posSet.has(Number(r.position)));

  const order = new Map(c.positions.map((p, i) => [Number(p), i]));
  filtered.sort(
    (a, b) =>
      (order.get(Number(a.position)) ?? 999999) -
      (order.get(Number(b.position)) ?? 999999)
  );

  return {
    json: {
      clusterIndex: idx + 1,
      clusterPositions: c.positions,
      rows: filtered,
    },
  };
});

return out;

// Extract organic search results and wrap them into a single item
const results = $json.organic_results || [];

// Tuning knobs
const MAX_ROWS = 12;

// Optional: Domains/Patterns, die oft Noise sind
const EXCLUDE_PATTERNS = [
  /linkedin\.com\/pub\/dir/i,           // LinkedIn people directory
  /quicktransportsolutions\.com/i,      // random business registry
  /westdermatology\.com/i,              // unrelated medical pages
  /gisantamaria\.com/i,                 // unrelated medical pages
  /nytimes\.com\/athletic/i             // unrelated sports article
];

function shouldExclude(link) {
  if (!link) return false;
  return EXCLUDE_PATTERNS.some((re) => re.test(link));
}

// Map each result to a simplified object, filter noise, trim snippets
const rows = results
  .filter(r => r && r.link && r.title)
  .filter(r => !shouldExclude(r.link))
  .map(r => ({
    position: r.position,
    title: String(r.title).replace(/\s+/g, " ").trim(),
    snippet: r.snippet,
    link: r.link
  }))
  .slice(0, MAX_ROWS);

// Optionally include the original query if available
const query = ($json.search_parameters?.q || "").trim() || null;

// Return a single item containing all rows
return [
  {
    json: {
      query,
      rows
    }
  }
];

/**
 * Erwarteter Kontext:
 * - aktuelles Item ($json):
 *   {
 *     rows: [ { position, title, snippet, link }, ... ]
 *   }
 *
 * - Clustering-Node:
 *   {
 *     clusters: [ { positions: number[] }, ... ],
 *     unsicher: number[]
 *   }
 */

// -------------------------------
// 1) Gesamtanzahl aller Links
// -------------------------------
let totalLinks = 0;

try {
  const clustering = $items('Cluster Formatter')[0]?.json ?? {};
  const clusters = Array.isArray(clustering.clusters) ? clustering.clusters : [];
  const unsicher = Array.isArray(clustering.unsicher) ? clustering.unsicher : [];

  for (const c of clusters) {
    if (Array.isArray(c.positions)) {
      totalLinks += c.positions.length;
    }
  }

  totalLinks += unsicher.length;
} catch {
  totalLinks = 0;
}

// -------------------------------
// 2) Zugewiesene Links (Cluster)
// -------------------------------
const assignedLinks = Array.isArray($json.rows)
  ? $json.rows.length
  : 0;

// -------------------------------
// 3) Confidence berechnen
// -------------------------------
let confidence = 0;

if (totalLinks > 0) {
  confidence = assignedLinks / totalLinks;
}

// harte Grenzen (Sicherheit)
confidence = Math.max(0, Math.min(1, confidence));

// -------------------------------
// 4) Ergebnis zurückgeben
// -------------------------------
return {
  json: {
    confidence
  }
};

let text = "";

for (const item of $items()) {
  const rows = $('ParseHints').first().json.rows ?? [];

  for (const row of rows) {
    text += `Title: ${row.title}\n`;
    text += `Link: ${row.link}\n`;
    text += `Summary: ${row.snippet}\n`;
    text += `\n---------------------------\n\n`;
  }
}

return [{
  json: {
    combined: text
  }
}];

// 1) Rohtext holen (passe den Pfad an deinen Node an)
const raw = $json.text ?? $json.response ?? "";

// 2) JSON aus dem Text extrahieren + parsen
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  const match = String(raw).match(/\{[\s\S]*\}/);
  if (!match) throw new Error("Kein JSON-Objekt im Text gefunden.");
  parsed = JSON.parse(match[0]);
}

// 3) Jetzt hast du echte Arrays
const clusters = Array.isArray(parsed.clusters) ? parsed.clusters : [];
const unsicher = Array.isArray(parsed.unsicher) ? parsed.unsicher : [];

// Ausgabe (damit nachfolgende Nodes direkt $json.clusters nutzen können)
return [{
  json: {
    clusters,
    unsicher
  }
}];
